_STORAGE_TAIL = '''
_dirs = __DIRS__
_key = __KEY__
_result = {"key": _key, "dirs": _dirs, "directory": None, "state": None}
for _dir in _dirs:
    _state = read_state(_dir, _key)
    if _state is not None:
        _result["directory"] = _dir
        _result["state"] = _state
        break
print(json.dumps(_result, ensure_ascii=False))
'''


def openblender_storage_program(dirs: list[str], key: str) -> str:
    """Build a standalone program that prints the OpenBlender app-state document."""
    tail = _STORAGE_TAIL.replace("__DIRS__", json.dumps(dirs)).replace("__KEY__", json.dumps(key))
    return LOCAL_STORAGE_SOURCE + tail

