class BlenderSceneEvaluator(BaseEvaluator):
    """Verify the scene recorded in the saved ``.blend`` documents."""

    DEFAULT_TIMEOUT = 120
    DEFAULT_TOLERANCE = 0.02
    PASS_MESSAGE = "Blender scene checks passed"
    FAIL_MESSAGE = "Blender scene checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        blend_path = str(params.get("blend_path") or "").strip()
        if not blend_path:
            return EvalResult(status=EvalStatus.ERROR, message="evaluation.params.blend_path is required")

        tolerance = self._number(params.get("tolerance"), self.DEFAULT_TOLERANCE)
        color_tolerance = self._number(params.get("color_tolerance"), tolerance)
        timeout = int(params.get("timeout", self.DEFAULT_TIMEOUT) or self.DEFAULT_TIMEOUT)

        additional_blends = params.get("additional_blends") or []
        if additional_blends and not isinstance(additional_blends, list):
            return EvalResult(status=EvalStatus.ERROR, message="evaluation.params.additional_blends must be a list")
        text_artifacts = params.get("text_artifacts") or []
        if text_artifacts and not isinstance(text_artifacts, list):
            return EvalResult(status=EvalStatus.ERROR, message="evaluation.params.text_artifacts must be a list")

        targets = [
            {
                "label": "primary",
                "blend_path": blend_path,
                "render": dict(params.get("render") or {}),
                "scene": dict(params.get("scene") or {}),
                "objects": list(params.get("objects") or []),
                "active_object": params.get("active_object"),
            }
        ]
        for index, item in enumerate(additional_blends, start=1):
            if not isinstance(item, Mapping):
                continue
            extra_path = str(item.get("blend_path") or "").strip()
            if not extra_path:
                return EvalResult(status=EvalStatus.ERROR, message="additional_blends[%d] missing blend_path" % index)
            targets.append(
                {
                    "label": str(item.get("label") or "additional_%d" % index),
                    "blend_path": extra_path,
                    "render": dict(item.get("render") or {}),
                    "scene": dict(item.get("scene") or {}),
                    "objects": list(item.get("objects") or []),
                    "active_object": item.get("active_object"),
                }
            )

        payloads: dict[str, Any] = {}
        for target in targets:
            label = str(target["label"])
            try:
                payload = self._inspect_blend(controller, str(target["blend_path"]), timeout)
            except BlenderUnreadable as exc:
                payloads[label] = {"error": str(exc)}
                return EvalResult(status=EvalStatus.FAIL, message="%s: %s" % (label, exc), metadata=payloads)
            except Exception as exc:
                return EvalResult(
                    status=EvalStatus.ERROR,
                    message="%s: Blender inspection failed: %s: %s" % (label, type(exc).__name__, exc),
                    metadata=payloads,
                )

            if payload.get("missing"):
                payloads[label] = payload
                return EvalResult(
                    status=EvalStatus.FAIL,
                    message="%s: saved scene file is absent: %s" % (label, payload.get("blend_path")),
                    metadata=payloads,
                )
            if payload.get("failed"):
                payloads[label] = payload
                return EvalResult(
                    status=EvalStatus.FAIL,
                    message="%s: Blender could not open the saved scene: %s"
                    % (label, str(payload.get("error") or payload.get("output") or "")[-300:]),
                    metadata=payloads,
                )
            if payload.get("unreadable"):
                payloads[label] = payload
                return EvalResult(
                    status=EvalStatus.FAIL,
                    message="%s: saved scene state could not be read from the file" % label,
                    metadata=payloads,
                )

            try:
                self._validate_render(dict(target.get("render") or {}), dict(payload.get("render") or {}))
                self._validate_scene(dict(target.get("scene") or {}), payload, target.get("active_object"), tolerance)
                self._validate_objects(
                    list(target.get("objects") or []),
                    dict(payload.get("objects") or {}),
                    tolerance=tolerance,
                    color_tolerance=color_tolerance,
                )
            except AssertionError as exc:
                payloads[label] = payload
                return EvalResult(status=EvalStatus.FAIL, message="%s: %s" % (label, exc), metadata=payloads)
            payloads[label] = payload

        if text_artifacts:
            try:
                payloads["text_artifacts"] = self._validate_text_artifacts(controller, text_artifacts, timeout)
            except AssertionError as exc:
                return EvalResult(status=EvalStatus.FAIL, message=str(exc), metadata=payloads)
            except Exception as exc:
                return EvalResult(
                    status=EvalStatus.ERROR,
                    message="text artifact validation failed: %s: %s" % (type(exc).__name__, exc),
                    metadata=payloads,
                )

        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=payloads)

    # ------------------------------------------------------------------ read
    @staticmethod
    def _inspect_blend(controller: Any, blend_path: str, timeout: int) -> dict[str, Any]:
        if not blend_path:
            raise BlenderUnreadable("a scene file path is required")
        program = _GUEST_PROGRAM.replace("__BLEND_PATH__", json.dumps(blend_path)).replace(
            "__INSPECT_SOURCE__", repr(_INSPECT_SOURCE)
        )
        if controller is None or not hasattr(controller, "run_python_script"):
            raise BlenderUnreadable("controller.run_python_script is required")
        raw = controller.run_python_script(program, timeout=timeout)
        if not isinstance(raw, Mapping):
            raise BlenderUnreadable("runtime returned no result mapping")
        output = str(raw.get("stdout") or raw.get("output") or "").strip()
        if int(raw.get("returncode", -1)) != 0:
            raise BlenderUnreadable(str(raw.get("stderr") or "") or output or "runtime command failed")
        try:
            return dict(json.loads(output.splitlines()[-1]))
        except (ValueError, IndexError) as exc:
            raise RuntimeError("Blender inspection output was not JSON: %s" % exc) from exc

    @staticmethod
    def _validate_text_artifacts(controller: Any, artifacts: list[Any], timeout: int) -> dict[str, Any]:
        request = json.dumps(artifacts, ensure_ascii=False)
        program = _ARTIFACT_PROGRAM.replace("__ARTIFACTS__", repr(request))
        if controller is None or not hasattr(controller, "run_python_script"):
            raise RuntimeError("controller.run_python_script is required")
        raw = controller.run_python_script(program, timeout=timeout)
        if not isinstance(raw, Mapping):
            raise RuntimeError("runtime returned no result mapping")
        output = str(raw.get("stdout") or raw.get("output") or "").strip()
        if int(raw.get("returncode", -1)) != 0:
            raise RuntimeError(str(raw.get("stderr") or "") or output or "runtime command failed")
        payload = json.loads(output.splitlines()[-1])
        by_path = {str(item.get("path") or ""): dict(item) for item in payload.get("results") or []}
        for item in artifacts:
            if not isinstance(item, Mapping):
                continue
            path = str(item.get("path") or "")
            actual = by_path.get(path)
            assert actual is not None, "missing text artifact payload for %s" % path
            assert bool(actual.get("exists")), "expected text artifact to exist: %s" % path
            content = str(actual.get("content") or "")
            if "equals" in item:
                assert content == str(item.get("equals") or ""), "text artifact mismatch for %s" % path
            if "contains" in item:
                assert str(item.get("contains") or "") in content, (
                    "expected text artifact %s to contain %r" % (path, item.get("contains"))
                )
        return payload

    # ---------------------------------------------------------------- checks
    @staticmethod
    def _number(value: Any, default: float) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return float(default)

    @staticmethod
    def _validate_render(expectations: Mapping[str, Any], actual: Mapping[str, Any]) -> None:
        for key, expected in expectations.items():
            assert key in actual, "missing render field: %s" % key
            assert actual[key] == expected, "expected render %s=%r, got %r" % (key, expected, actual[key])

    @staticmethod
    def _assert_close_vector(label: str, expected: Any, actual: Any, tolerance: float) -> None:
        expected_list = list(expected or [])
        actual_list = list(actual or [])
        assert len(expected_list) == len(actual_list), "%s length mismatch" % label
        for index, (wanted, seen) in enumerate(zip(expected_list, actual_list)):
            assert abs(float(wanted) - float(seen)) <= tolerance, (
                "%s[%d] expected %.4f, got %.4f" % (label, index, float(wanted), float(seen))
            )

    @staticmethod
    def _assert_scalar(label: str, expected: Any, actual: Any, tolerance: float) -> None:
        assert actual is not None, "%s is missing" % label
        assert abs(float(expected) - float(actual)) <= tolerance, (
            "%s expected %.4f, got %.4f" % (label, float(expected), float(actual))
        )

    def _validate_scene(
        self,
        expectations: Mapping[str, Any],
        payload: Mapping[str, Any],
        active_object: Any,
        tolerance: float,
    ) -> None:
        wanted_active = expectations.get("active_object", active_object)
        if wanted_active is not None:
            expected = str(wanted_active).strip()
            if expected:
                actual = str(payload.get("active_object") or "").strip()
                assert actual == expected, "active_object expected %r, got %r" % (expected, actual)
        counts = expectations.get("object_type_counts")
        if isinstance(counts, Mapping):
            observed_counts = dict(payload.get("object_type_counts") or {})
            for kind, wanted in counts.items():
                observed = observed_counts.get(str(kind))
                assert observed == wanted, (
                    "object_type_counts[%s] expected %r, got %r" % (kind, wanted, observed)
                )

    def _validate_objects(
        self,
        expectations: list[Any],
        actual: Mapping[str, Any],
        *,
        tolerance: float,
        color_tolerance: float,
    ) -> None:
        for item in expectations:
            if not isinstance(item, Mapping):
                continue
            name = str(item.get("name") or "").strip()
            assert name, "object expectation missing name"
            observed = dict(actual.get(name) or {})
            assert observed, "missing object in the saved scene: %s" % name

            if "type" in item:
                expected = str(item.get("type") or "").strip()
                seen = str(observed.get("type") or "").strip()
                assert seen == expected, "%s.type expected %r, got %r" % (name, expected, seen)
            if "data_name" in item:
                expected = str(item.get("data_name") or "").strip()
                seen = str(observed.get("data_name") or "").strip()
                assert seen == expected, "%s.data_name expected %r, got %r" % (name, expected, seen)
            if "parent" in item:
                expected = str(item.get("parent") or "").strip()
                seen = str(observed.get("parent") or "").strip()
                assert seen == expected, "%s.parent expected %r, got %r" % (name, expected, seen)
            if "hide_viewport" in item:
                expected = bool(item.get("hide_viewport"))
                assert bool(observed.get("hide_viewport")) == expected, (
                    "%s.hide_viewport expected %r, got %r" % (name, expected, observed.get("hide_viewport"))
                )
            if "hide_render" in item:
                expected = bool(item.get("hide_render"))
                assert bool(observed.get("hide_render")) == expected, (
                    "%s.hide_render expected %r, got %r" % (name, expected, observed.get("hide_render"))
                )
            if "collection" in item:
                wanted = str(item.get("collection") or "").strip()
                assert wanted in [str(value) for value in observed.get("collections") or []], (
                    "%s is not in collection %r" % (name, wanted)
                )

            if "location" in item:
                self._assert_close_vector("%s.location" % name, item.get("location"), observed.get("location"), tolerance)
            if "rotation_degrees" in item:
                self._assert_close_vector(
                    "%s.rotation_degrees" % name, item.get("rotation_degrees"), observed.get("rotation_degrees"), tolerance
                )
            if "scale" in item:
                self._assert_close_vector("%s.scale" % name, item.get("scale"), observed.get("scale"), tolerance)
            for key, source in (
                ("location", "location_components"),
                ("rotation_degrees", "rotation_components"),
                ("scale", "scale_components"),
            ):
                wanted_axes = item.get(source)
                if not isinstance(wanted_axes, Mapping):
                    continue
                axes = ("x", "y", "z")
                observed_values = list(observed.get(key) or [])
                for axis, wanted in wanted_axes.items():
                    index = axes.index(str(axis).lower()) if str(axis).lower() in axes else None
                    assert index is not None and index < len(observed_values), (
                        "%s.%s has no %s component" % (name, key, axis)
                    )
                    assert abs(float(wanted) - float(observed_values[index])) <= tolerance, (
                        "%s.%s.%s expected %.4f, got %.4f" % (name, key, axis, float(wanted), float(observed_values[index]))
                    )

            if "material_name" in item:
                expected = str(item.get("material_name") or "").strip()
                seen = str(observed.get("material_name") or "").strip()
                assert seen == expected, "%s.material_name expected %r, got %r" % (name, expected, seen)
            if "material_diffuse_color" in item:
                self._assert_close_vector(
                    "%s.material_diffuse_color" % name,
                    item.get("material_diffuse_color"),
                    observed.get("material_diffuse_color"),
                    color_tolerance,
                )
            if "material_metallic" in item:
                self._assert_scalar(
                    "%s.material_metallic" % name, item.get("material_metallic"), observed.get("material_metallic"), tolerance
                )
            if "material_roughness" in item:
                self._assert_scalar(
                    "%s.material_roughness" % name, item.get("material_roughness"), observed.get("material_roughness"), tolerance
                )
            material = item.get("material")
            if isinstance(material, Mapping):
                if "name" in material:
                    expected = str(material.get("name") or "").strip()
                    seen = str(observed.get("material_name") or "").strip()
                    assert seen == expected, "%s.material.name expected %r, got %r" % (name, expected, seen)
                if "color" in material:
                    self._assert_close_vector(
                        "%s.material.color" % name, material.get("color"), observed.get("material_diffuse_color"), color_tolerance
                    )
                if "metallic" in material:
                    self._assert_scalar(
                        "%s.material.metallic" % name, material.get("metallic"), observed.get("material_metallic"), tolerance
                    )
                if "roughness" in material:
                    self._assert_scalar(
                        "%s.material.roughness" % name, material.get("roughness"), observed.get("material_roughness"), tolerance
                    )
            if "all_polygons_smooth" in item:
                expected = bool(item.get("all_polygons_smooth"))
                assert observed.get("all_polygons_smooth") == expected, (
                    "%s.all_polygons_smooth expected %r, got %r"
                    % (name, expected, observed.get("all_polygons_smooth"))
                )

            if "modifiers" in item:
                observed_modifiers = dict(observed.get("modifiers") or {})
                for wanted_modifier in list(item.get("modifiers") or []):
                    if not isinstance(wanted_modifier, Mapping):
                        continue
                    modifier_name = str(wanted_modifier.get("name") or "").strip()
                    assert modifier_name, "%s.modifiers expectation missing name" % name
                    seen_modifier = dict(observed_modifiers.get(modifier_name) or {})
                    assert seen_modifier, "%s missing modifier %r" % (name, modifier_name)
                    if "type" in wanted_modifier:
                        expected = str(wanted_modifier.get("type") or "").strip()
                        seen = str(seen_modifier.get("type") or "").strip()
                        assert seen == expected, (
                            "%s.%s.type expected %r, got %r" % (name, modifier_name, expected, seen)
                        )
                    for key in ("width", "thickness", "amount"):
                        if key in wanted_modifier:
                            self._assert_scalar(
                                "%s.%s.%s" % (name, modifier_name, key),
                                wanted_modifier.get(key),
                                seen_modifier.get(key),
                                tolerance,
                            )
                    if "segments" in wanted_modifier:
                        expected = int(wanted_modifier.get("segments"))
                        seen = int(seen_modifier.get("segments"))
                        assert seen == expected, (
                            "%s.%s.segments expected %d, got %d" % (name, modifier_name, expected, seen)
                        )

            if "light_energy" in item:
                self._assert_scalar("%s.light_energy" % name, item.get("light_energy"), observed.get("light_energy"), tolerance)
            if "light_type" in item:
                expected = str(item.get("light_type") or "").strip()
                seen = str(observed.get("light_type") or "").strip()
                assert seen == expected, "%s.light_type expected %r, got %r" % (name, expected, seen)
            if "light_color" in item:
                self._assert_close_vector(
                    "%s.light_color" % name, item.get("light_color"), observed.get("light_color"), color_tolerance
                )
            if "camera_lens" in item:
                self._assert_scalar("%s.camera_lens" % name, item.get("camera_lens"), observed.get("camera_lens"), tolerance)
            if "camera_clip_start" in item:
                self._assert_scalar(
                    "%s.camera_clip_start" % name, item.get("camera_clip_start"), observed.get("camera_clip_start"), tolerance
                )


class BlenderUnreadable(RuntimeError):
    """Raised when the saved scene file cannot be opened or read back."""


class OpenBlenderStateEvaluator(BaseEvaluator):
    """Verify the OpenBlender web-app state recorded in Local Storage."""

    DEFAULT_TOLERANCE = 0.03
    PASS_MESSAGE = "OpenBlender state checks passed"
    FAIL_MESSAGE = "OpenBlender state checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        try:
            observed = self._read_document(context, params)
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenBlender app state could not be read: %s: %s" % (type(exc).__name__, exc),
            )

        state = observed.get("state")
        if not isinstance(state, Mapping):
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenBlender app state is absent: %s" % OPENBLENDER_STATE_KEY,
                metadata=observed,
            )

        tolerance = self._number(params.get("tolerance"), self.DEFAULT_TOLERANCE)
        projects = [dict(item) for item in state.get("projects") or [] if isinstance(item, Mapping)]
        materials = {
            str(item.get("id") or ""): dict(item)
            for item in state.get("materials") or []
            if isinstance(item, Mapping)
        }
        project = self._resolve_project(projects, params, state)
        checks: list[dict[str, Any]] = []
        notes: list[str] = []

        if project is None:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenBlender app state contains no project matching the task",
                metadata=dict(observed),
            )

        expected_workspace = str(params.get("active_workspace") or "").strip()
        if expected_workspace:
            seen = str(state.get("activeWorkspace") or "").strip()
            self._add(checks, "active_workspace", expected_workspace, seen, seen == expected_workspace)

        expected_tab = str(params.get("active_property_tab") or "").strip()
        if expected_tab:
            seen = str(state.get("activePropertyTab") or "").strip()
            if seen:
                self._add(checks, "active_property_tab", expected_tab, seen, seen == expected_tab)
            else:
                notes.append("active_property_tab is not part of the stored app state")

        expected_engine = str(params.get("render_engine") or "").strip()
        if expected_engine:
            seen = str(
                project.get("renderEngine")
                or (project.get("render") or {}).get("engine") if isinstance(project.get("render"), Mapping) else ""
            ).strip()
            if not seen:
                seen = str(state.get("renderEngine") or state.get("engine") or "").strip()
            self._add(checks, "render_engine", expected_engine, seen, seen == expected_engine)

        if params.get("current_frame") is not None:
            wanted = int(params["current_frame"])
            raw = project.get("currentFrame", project.get("frame", state.get("currentFrame")))
            seen = int(raw) if raw is not None else None
            self._add(checks, "current_frame", wanted, seen, seen == wanted)

        self._validate_mapping(checks, "output", dict(params.get("output") or {}), self._output_of(project), tolerance)
        self._validate_mapping(checks, "render", dict(params.get("render") or {}), self._render_of(project), tolerance)
        self._validate_mapping(checks, "layers", dict(params.get("layers") or {}), self._layers_of(project, state), tolerance)
        self._validate_objects(
            checks,
            list(params.get("objects") or []),
            [dict(item) for item in project.get("objects") or [] if isinstance(item, Mapping)],
            materials,
            tolerance,
        )
        self._validate_keyframes(
            checks,
            list(params.get("keyframes") or []),
            project,
            [dict(item) for item in project.get("objects") or [] if isinstance(item, Mapping)],
            tolerance,
        )

        metadata = dict(observed)
        metadata["project"] = {"id": project.get("id"), "name": project.get("name")}
        metadata["checks"] = checks
        metadata["unobservable_conditions"] = notes
        metadata["failures"] = [item["check_id"] for item in checks if not item["passed"]]
        if not checks:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the task declares no OpenBlender state to verify",
                metadata=metadata,
            )
        if metadata["failures"]:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenBlender state checks failed: %s" % ", ".join(metadata["failures"][:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=metadata)

    # ------------------------------------------------------------------ read
    @staticmethod
    def _storage_dirs(params: Mapping[str, Any]) -> list[str]:
        declared = params.get("storage_dirs") or params.get("leveldb_dir")
        dirs: list[str] = []
        if isinstance(declared, (list, tuple)):
            dirs.extend(str(item) for item in declared if item)
        elif declared:
            dirs.append(str(declared))
        for root in OPENBLENDER_STORAGE_DIRS:
            if root not in dirs:
                dirs.append(root)
        return [guest_path(directory) for directory in dirs]

    def _read_document(self, context: Mapping[str, Any], params: Mapping[str, Any]) -> dict[str, Any]:
        key = str(params.get("storage_key") or OPENBLENDER_STATE_KEY)
        dirs = self._storage_dirs(params)
        timeout = int(params.get("timeout", 60) or 60)
        controller = context.get("controller")
        if controller is not None and hasattr(controller, "run_python_script"):
            raw = controller.run_python_script(openblender_storage_program(dirs, key), timeout=timeout)
            if not isinstance(raw, Mapping):
                raise RuntimeError("runtime returned no result mapping")
            output = str(raw.get("stdout") or raw.get("output") or "").strip()
            if int(raw.get("returncode", -1)) != 0:
                raise RuntimeError(str(raw.get("stderr") or "") or output or "runtime command failed")
            try:
                return dict(json.loads(output.splitlines()[-1]))
            except (ValueError, IndexError) as exc:
                raise RuntimeError("runtime output was not JSON: %s" % exc) from exc
        result: dict[str, Any] = {"key": key, "dirs": dirs, "directory": None, "state": None}
        for directory in dirs:
            state = read_state(directory, key)
            if state is not None:
                result["directory"] = directory
                result["state"] = state
                break
        return result

    # ---------------------------------------------------------------- checks
    @staticmethod
    def _number(value: Any, default: float) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return float(default)

    @staticmethod
    def _add(checks: list[dict[str, Any]], check_id: str, expected: Any, observed: Any, passed: bool) -> None:
        checks.append({"check_id": check_id, "passed": bool(passed), "expected": expected, "observed": observed})

    def _add_close(
        self, checks: list[dict[str, Any]], check_id: str, expected: Any, observed: Any, tolerance: float
    ) -> None:
        passed = False
        if observed is not None:
            try:
                passed = abs(float(expected) - float(observed)) <= tolerance
            except (TypeError, ValueError):
                passed = False
        self._add(checks, check_id, expected, observed, passed)

    def _add_vector(
        self, checks: list[dict[str, Any]], check_id: str, expected: Any, observed: Any, tolerance: float
    ) -> None:
        expected_list = list(expected or [])
        observed_list = list(observed or [])
        passed = len(expected_list) == len(observed_list)
        if passed:
            for wanted, seen in zip(expected_list, observed_list):
                try:
                    if abs(float(wanted) - float(seen)) > tolerance:
                        passed = False
                        break
                except (TypeError, ValueError):
                    passed = False
                    break
        self._add(checks, check_id, expected_list, observed_list, passed)

    @staticmethod
    def _normalize_color(value: Any) -> list[float]:
        if isinstance(value, str):
            text = value.strip()
            if text.startswith("#") and len(text) in {7, 9}:
                channels = [int(text[index:index + 2], 16) / 255.0 for index in range(1, len(text), 2)]
                if len(channels) == 3:
                    channels.append(1.0)
                return channels
        if isinstance(value, (list, tuple)):
            channels = [float(channel) for channel in value]
            if len(channels) == 3:
                channels.append(1.0)
            return channels
        return []

    def _validate_mapping(
        self,
        checks: list[dict[str, Any]],
        label: str,
        expectations: Mapping[str, Any],
        observed: Mapping[str, Any],
        tolerance: float,
    ) -> None:
        for key, wanted in expectations.items():
            seen = observed.get(key) if isinstance(observed, Mapping) else None
            if isinstance(wanted, bool):
                self._add(
                    checks,
                    "%s.%s" % (label, key),
                    bool(wanted),
                    None if seen is None else bool(seen),
                    seen is not None and bool(seen) == bool(wanted),
                )
            elif isinstance(wanted, (int, float)):
                self._add_close(checks, "%s.%s" % (label, key), wanted, seen, tolerance)
            elif isinstance(wanted, (list, tuple)):
                self._add_vector(checks, "%s.%s" % (label, key), wanted, seen, tolerance)
            else:
                self._add(checks, "%s.%s" % (label, key), wanted, seen, seen == wanted)

    @staticmethod
    def _output_of(project: Mapping[str, Any]) -> Mapping[str, Any]:
        value = project.get("output")
        return value if isinstance(value, Mapping) else {}

    @staticmethod
    def _render_of(project: Mapping[str, Any]) -> Mapping[str, Any]:
        value = project.get("render")
        return value if isinstance(value, Mapping) else {}

    @staticmethod
    def _layers_of(project: Mapping[str, Any], state: Mapping[str, Any]) -> Mapping[str, Any]:
        for candidate in (project.get("viewLayer"), project.get("layers"), state.get("layers"), state.get("viewLayer")):
            if isinstance(candidate, Mapping):
                return candidate
        return {}

    @staticmethod
    def _resolve_project(
        projects: list[dict[str, Any]], params: Mapping[str, Any], state: Mapping[str, Any]
    ) -> dict[str, Any] | None:
        project_id = str(params.get("project_id") or "").strip()
        project_name = str(params.get("project_name") or "").strip()
        if project_id:
            for project in projects:
                if str(project.get("id") or "") == project_id:
                    return project
            return None
        if project_name:
            for project in projects:
                if str(project.get("name") or "") == project_name:
                    return project
            return None
        current_id = str(state.get("currentProjectId") or "")
        for project in projects:
            if str(project.get("id") or "") == current_id:
                return project
        return projects[0] if projects else None

    def _validate_objects(
        self,
        checks: list[dict[str, Any]],
        expectations: list[Any],
        observed_objects: list[dict[str, Any]],
        materials: Mapping[str, Mapping[str, Any]],
        tolerance: float,
    ) -> None:
        for item in expectations:
            if not isinstance(item, Mapping):
                continue
            name = str(item.get("name") or "").strip()
            if not name:
                continue
            obj = next((candidate for candidate in observed_objects if str(candidate.get("name") or "") == name), None)
            self._add(checks, "object:%s" % name, {"present": True}, {"present": obj is not None}, obj is not None)
            if obj is None:
                continue
            for key in ("type", "collection"):
                if key in item:
                    wanted = str(item.get(key) or "")
                    seen = str(obj.get(key) or "")
                    self._add(checks, "%s.%s" % (name, key), wanted, seen, seen == wanted)
            for key in ("location", "rotation", "scale"):
                if key in item:
                    self._add_vector(checks, "%s.%s" % (name, key), item.get(key), obj.get(key), tolerance)
            for source, vector in (
                ("location_components", "location"),
                ("rotation_components", "rotation"),
                ("scale_components", "scale"),
            ):
                wanted_components = item.get(source)
                if not isinstance(wanted_components, Mapping):
                    continue
                axes = ("x", "y", "z")
                vector_values = list(obj.get(vector) or [])
                for axis, wanted in wanted_components.items():
                    index = axes.index(str(axis).lower()) if str(axis).lower() in axes else None
                    seen = vector_values[index] if index is not None and index < len(vector_values) else None
                    self._add_close(checks, "%s.%s.%s" % (name, vector, axis), wanted, seen, tolerance)

            material_id = str(obj.get("materialId") or "")
            material = dict(materials.get(material_id) or {})
            if "material_name" in item:
                wanted = str(item.get("material_name") or "")
                seen = str(material.get("name") or "")
                self._add(checks, "%s.material_name" % name, wanted, seen, seen == wanted)
            wanted_material = item.get("material")
            if isinstance(wanted_material, Mapping):
                self._add(checks, "%s.material" % name, {"present": True}, {"present": bool(material)}, bool(material))
                if "name" in wanted_material:
                    wanted = str(wanted_material.get("name") or "")
                    seen = str(material.get("name") or "")
                    self._add(checks, "%s.material.name" % name, wanted, seen, seen == wanted)
                for key in ("roughness", "metallic"):
                    if key in wanted_material:
                        self._add_close(checks, "%s.material.%s" % (name, key), wanted_material.get(key), material.get(key), tolerance)
                if "color" in wanted_material:
                    self._add_vector(
                        checks,
                        "%s.material.color" % name,
                        self._normalize_color(wanted_material.get("color")),
                        self._normalize_color(material.get("color")),
                        tolerance,
                    )
                if wanted_material.get("dark_blue"):
                    channels = self._normalize_color(material.get("color"))
                    red, green, blue = (channels + [0.0, 0.0, 0.0])[:3]
                    passed = blue > red and blue > green and max(red, green, blue) <= 0.40
                    self._add(checks, "%s.material.dark_blue" % name, True, channels, passed)

            modified = item.get("modifiers")
            if isinstance(modified, list):
                observed_modifiers = [dict(mod) for mod in obj.get("modifiers") or [] if isinstance(mod, Mapping)]
                for wanted_modifier in modified:
                    if not isinstance(wanted_modifier, Mapping):
                        continue
                    modifier_name = str(wanted_modifier.get("name") or "").strip()
                    found = next(
                        (mod for mod in observed_modifiers if str(mod.get("name") or "") == modifier_name), None
                    )
                    self._add(
                        checks,
                        "%s.modifier:%s" % (name, modifier_name),
                        {"present": True},
                        {"present": found is not None},
                        found is not None,
                    )
                    if found is None:
                        continue
                    if "type" in wanted_modifier:
                        wanted = str(wanted_modifier.get("type") or "")
                        seen = str(found.get("type") or "")
                        self._add(checks, "%s.%s.type" % (name, modifier_name), wanted, seen, seen == wanted)
                    settings = dict(found.get("settings") or {})
                    for key in ("amount", "thickness", "segments"):
                        if key in wanted_modifier:
                            self._add_close(
                                checks,
                                "%s.%s.%s" % (name, modifier_name, key),
                                wanted_modifier.get(key),
                                settings.get(key),
                                tolerance,
                            )

    def _validate_keyframes(
        self,
        checks: list[dict[str, Any]],
        expectations: list[Any],
        project: Mapping[str, Any],
        observed_objects: list[dict[str, Any]],
        tolerance: float,
    ) -> None:
        for item in expectations:
            if not isinstance(item, Mapping):
                continue
            object_name = str(item.get("object") or item.get("name") or "").strip()
            if not object_name or item.get("frame") is None:
                continue
            frame = int(item["frame"])
            obj = next((candidate for candidate in observed_objects if str(candidate.get("name") or "") == object_name), None)
            self._add(
                checks,
                "keyframe:%s@%d" % (object_name, frame),
                {"object": object_name, "frame": frame},
                {"present_object": obj is not None},
                obj is not None,
            )
            if obj is None:
                continue
            recorded = list(obj.get("keyframes") or [])
            flat_frames = {int(value) for value in recorded if isinstance(value, (int, float))}
            rich = [value for value in recorded if isinstance(value, Mapping)]
            rich_frames = {int(value.get("frame")) for value in rich if value.get("frame") is not None}
            present = frame in flat_frames or frame in rich_frames
            self._add(
                checks,
                "keyframe_frame:%s@%d" % (object_name, frame),
                {"frame": frame},
                {"frames": sorted(flat_frames | rich_frames)},
                present,
            )
            keyframe = next((value for value in rich if value.get("frame") is not None and int(value["frame"]) == frame), None)
            if keyframe is None:
                continue
            for key in ("location", "rotation", "scale"):
                if key in item and key in keyframe:
                    self._add_vector(checks, "%s.keyframe.%s" % (object_name, key), item.get(key), keyframe.get(key), tolerance)
            if "channels" in item:
                wanted_channels = {str(channel).strip().lower() for channel in item.get("channels") or []}
                seen_channels = {
                    str(channel).strip().lower()
                    for channel in (keyframe.get("channels") or keyframe.get("properties") or [])
                }
                missing = sorted(wanted_channels - seen_channels)
                self._add(
                    checks,
                    "keyframe_channels:%s@%d" % (object_name, frame),
                    sorted(wanted_channels),
                    sorted(seen_channels),
                    not missing,
                )

